-- A.3 "Key Algebraic Properties: Proving Expressions Are Equal" becomes a real
-- Nuanced Analysis row, the way A.1 and A.2 already are. Until now the section
-- existed only as (a) an entry in na_continuity.unit_sequence, (b) a packet
-- digest, and (c) a PDF uploaded to source_materials - so every packet after it
-- has been generated against a second-hand summary of a packet the platform did
-- not hold.
--
-- EVERY FIELD IS TRANSCRIBED FROM THE PRINT MASTER (source_materials
-- b368756b-4db9-452b-9270-bb681429faa5), not from the continuity digest, which
-- disagrees with the packet in several places - it records a fundraiser-ledger
-- context the packet never uses (Part 4 is a market stall), credits al-Karaji
-- (the packet credits Liu Hui and Yang Hui), and states the Part 6 identity in
-- a and b when the packet proves it in x and y. Those are left exactly as they
-- are here: this migration only aligns the digest's slug and title, which have
-- to match the packet row for the same reason A.1's and A.2's do.
--
-- WHAT THE MASTER DOES NOT CONTAIN, and is therefore null rather than invented:
-- materials, atl_statement and teacher_companion. A.3's template prints no
-- materials line, no ATL box and no teacher companion. draft_content is null
-- for the same reason it is null on all six existing packets (HANDOFF.md ss15):
-- the sandbox draft was never persisted, and editor-client.tsx loads
-- draft_content into the editor whenever it is present, so a partial write
-- would replace the packet with a near-empty draft the next time it is opened.
--
-- vocabulary is the tear-off command-term strip printed on page 1 (17 terms),
-- which is what this template uses the field for. parts holds all 8 printed
-- sections - Parts 0-6 and Zone (b), the B.1 pre-class prep that continuity
-- records as having shipped at the back of the A.3 bundle - with their
-- prerequisite boxes, command-term spotlights, the Part 1 translation table and
-- the two geometric readings. 32 questions, 124 marks.
insert into nuanced_analyses (
  id, slug, title, subtitle, course, course_id, owner_id, grade_level, section_code,
  syllabus_topics, prerequisites, materials, atl_statement,
  vocabulary, tok_provocations, parts, teacher_companion, draft_content,
  continuity_digest, sort_order, is_published
) values (
  'eda7bad6-0c7e-426d-97ff-d69e1d42c940',
  'key-algebraic-properties-proving-expressions-are-equal',
  'Key Algebraic Properties: Proving Expressions Are Equal',
  'Grade 9 Extended — Unit 1 Section A.3 (rolling bundle: Parts 0-6, then the B.1 pre-class prep in Zone (b))',
  'Grade 9 Mathematics (Extended)',
  'b1d3b183-5cbe-4994-ac3c-2a11120ed752',
  '44db5d56-f3ab-419f-9238-83377ac05b1d',
  'Grade 9',
  'A.3',
  array['Unit 1 — Section A.3'],
  array[]::text[],
  null,
  null,
  $json$[{"term": "Write down", "definition": "State a result without working, directly from given information."}, {"term": "State", "definition": "Give a specific name, value, or fact concisely, with no justification required."}, {"term": "Calculate", "definition": "Obtain a numerical answer, showing the relevant working."}, {"term": "Show that", "definition": "Prove a given result using a logical sequence of steps, making each step clear."}, {"term": "Prove", "definition": "Use a logical sequence of steps to establish a general result, with every step justified."}, {"term": "Justify", "definition": "Give valid reasons or evidence to support a conclusion."}, {"term": "Investigate", "definition": "Explore a mathematical situation methodically, often through pattern-finding, to arrive at a conjecture."}, {"term": "Determine", "definition": "Obtain the only possible answer, showing relevant working."}, {"term": "Explain", "definition": "Give a clear account of reasons or a process."}, {"term": "Hence", "definition": "Use a previously obtained result to derive the next result, without re-deriving it from scratch."}, {"term": "Verify", "definition": "Provide evidence that confirms a given statement is true, typically by substitution or direct check."}, {"term": "Compare", "definition": "Give an account of the similarities between two or more items."}, {"term": "Construct", "definition": "Display information in a diagrammatic or logical form."}, {"term": "Sketch", "definition": "Represent a situation by means of a diagram, without necessarily being drawn to exact scale."}, {"term": "Deduce", "definition": "Reach a conclusion from the information given, showing the reasoning used."}, {"term": "Interpret", "definition": "Use knowledge and understanding to recognise and explain a pattern or feature."}, {"term": "Describe", "definition": "Give a detailed account of a situation, process, or pattern."}]$json$::jsonb,
  $json$[{"id": "tok1", "body": "The commutative property says a+b = b+a for every pair of numbers you could ever choose. No one has ever checked every pair — there are infinitely many. Yet mathematicians treat this as certain, not merely 'true so far'. Is a mathematical proof a different kind of certainty from the certainty we get in science, where a law is only ever 'true in every experiment done so far'?"}, {"id": "tok2", "body": "A property like the distributive law can be shown two completely different ways: as an area diagram (two rectangles fitting together) and as a chain of symbols (a(b+c) = ab + ac). If both methods convince you the property is true, have you found one proof in two languages, or two independent proofs of the same fact? Does it matter which one you trust more?"}]$json$::jsonb,
  $json$[{"heading": "Part 0 — Activating Prior Knowledge", "prerequisiteBox": {"items": ["Distributive property from A.1: $60a + 30c = 30(2a+c)$, proved using an area diagram.", "Subtraction defined formally in A.2 as $a - b := a + (-b)$.", "Division defined formally in A.2 as $a \\div b := a \\times \\frac{1}{b}$.", "Equivalent expressions checked in A.2 by substituting a number and comparing results."]}, "spotlight": {"title": "State vs Show that", "body": "'State' means give the fact with no working — it is already known or directly readable. 'Show that' means you must display every logical step that leads to the given result, even if you are confident of the answer. In this packet, most of your marks come from Show that and Prove questions, so do not skip steps even when a result looks obvious."}, "questions": [{"tier": 1, "marks": 3, "prompt": "Calculate $4 \\times (5+3)$ in two different ways: (a) by evaluating the bracket first, and (b) by multiplying 4 by each term inside the bracket separately and adding the results. State whether the two answers match.", "answer": "(a) $4 \\times (5+3) = 4 \\times 8 = 32$. (b) $4 \\times 5 + 4 \\times 3 = 20 + 12 = 32$. The two answers match."}, {"tier": 1, "marks": 2, "prompt": "Using the definition $a - b := a + (-b)$ from A.2, rewrite $9 - 4$ as an addition, and calculate its value.", "answer": "$9 - 4 = 9 + (-4) = 5$."}, {"tier": 1, "marks": 3, "prompt": "State whether $7 - 3 = 3 - 7$. Justify your answer by writing both sides as additions using the definition from A.2 and comparing the results.", "hint": "$7-3 = 7+(-3)$. $3-7 = 3+(-7)$. Calculate both.", "answer": "$7 - 3 = 7 + (-3) = 4$ and $3 - 7 = 3 + (-7) = -4$. Since $4 \\neq -4$, the statement is false: $7 - 3 \\neq 3 - 7$."}, {"tier": 1, "marks": 3, "prompt": "In A.1 it was shown that $60a + 30c = 30(2a + c)$ using an area-model argument. Verify this result numerically for $a = 2$ and $c = 4$ by calculating both sides.", "answer": "Left side: $60(2) + 30(4) = 120 + 120 = 240$. Right side: $30(2 \\times 2 + 4) = 30(8) = 240$. Both sides equal 240, so the result is verified for these values."}]}, {"heading": "Part 1 — Commutative and Associative Properties: Conjecture from Evidence", "prerequisiteBox": {"items": ["A property is a rule that is claimed to hold for every number, not just for one example.", "'Commute' means to swap places — a commutative property lets you swap the order of two numbers.", "'Associate' means to group — an associative property lets you regroup which two numbers are combined first."]}, "spotlight": {"title": "Investigate vs Prove", "body": "'Investigate' means explore several numeric cases methodically to notice a pattern and state it as a conjecture — you are not yet required to show it works for every possible number. 'Prove' means establish the conjecture as true for every number, using logical steps rather than more examples. Part 1 asks you to Investigate; Part 3 will later ask you to Prove."}, "translationTable": {"caption": "From everyday language to formal property names", "rows": [{"informal": "You can add two numbers in either order.", "formal": "Commutative property of addition: $a + b = b + a$"}, {"informal": "You can multiply two numbers in either order.", "formal": "Commutative property of multiplication: $a \\times b = b \\times a$"}, {"informal": "When adding three numbers, it does not matter which two you add first.", "formal": "Associative property of addition: $(a + b) + c = a + (b + c)$"}, {"informal": "When multiplying three numbers, it does not matter which two you multiply first.", "formal": "Associative property of multiplication: $(a \\times b) \\times c = a \\times (b \\times c)$"}]}, "questions": [{"tier": 1, "marks": 4, "prompt": "Investigate the statement $a + b = b + a$ by calculating both sides for three different pairs of numbers of your choice, including at least one negative number. State your conjecture about addition in one sentence.", "answer": "Any three correct pairs, one involving a negative. For example $3+5 = 8$ and $5+3 = 8$; $-2+7 = 5$ and $7+(-2) = 5$; $0.5+4 = 4.5$ and $4+0.5 = 4.5$. Conjecture: adding two numbers gives the same result whichever order they are added in."}, {"tier": 1, "marks": 3, "prompt": "Investigate whether the same swapping rule holds for subtraction. Calculate $a - b$ and $b - a$ for $a = 10$, $b = 4$, then state whether subtraction is commutative.", "answer": "$10 - 4 = 6$ and $4 - 10 = -6$. Since $6 \\neq -6$, subtraction is not commutative."}, {"tier": 2, "marks": 4, "prompt": "Investigate the statement $(a + b) + c = a + (b + c)$ by calculating both sides for $a = 2$, $b = 5$, $c = 9$. State your conjecture about how addition can be grouped.", "hint": "Work out the bracket first on each side, then complete the remaining sum.", "answer": "Left side: $(2+5)+9 = 7+9 = 16$. Right side: $2+(5+9) = 2+14 = 16$. Both equal 16. Conjecture: when three numbers are added, it does not matter which two are added first."}, {"tier": 2, "marks": 4, "prompt": "Determine whether $(a - b) - c$ is equal to $a - (b - c)$ for $a = 20$, $b = 8$, $c = 3$. Explain what this tells you about subtraction.", "answer": "$(20-8)-3 = 12-3 = 9$ and $20-(8-3) = 20-5 = 15$. Since $9 \\neq 15$, the two are not equal, so subtraction is not associative — the grouping changes the result."}, {"tier": 2, "marks": 4, "prompt": "Compare the commutative property $a + b = b + a$ with the associative property $(a + b) + c = a + (b + c)$. Explain, in your own words, the difference between swapping two numbers and regrouping three numbers.", "answer": "The commutative property is about ORDER: it involves two numbers and lets them change places. The associative property is about GROUPING: it involves three numbers kept in the same order and only moves the brackets, changing which pair is combined first. Commutativity changes order without changing grouping; associativity changes grouping without changing order."}]}, {"heading": "Part 2 — The Distributive Property as a Proof Tool", "prerequisiteBox": {"items": ["A.1 showed $60a + 30c = 30(2a + c)$ using an area diagram — a rectangle of width 30 split into two smaller rectangles.", "A rectangle's area is length times width.", "Cutting a shape into pieces and reassembling it does not change its total area."]}, "spotlight": {"title": "Show that vs Prove", "body": "'Show that' guides you toward one specific given result through a fixed sequence of steps. 'Prove' asks you to establish a general statement (true for every value of the letters involved) and requires you to justify that the reasoning works for all cases, not only the case drawn in a diagram."}, "geometricReading": {"body": "The area diagram makes the distributive property visible without any symbols at all: a rectangle's area cannot depend on how you slice it into pieces, so 'one rectangle of length $(b+c)$' and 'two rectangles of lengths $b$ and $c$' must give the same total area. This is why the distributive property is often the first algebraic property that can be proved by a picture rather than only by manipulating symbols — the geometry and the algebra are two views of exactly one fact."}, "questions": [{"tier": 1, "marks": 3, "prompt": "A rectangle has width $a$ and is split along its length into two parts of length $b$ and $c$, so its total length is $b + c$. Construct a labelled diagram of this rectangle, showing the two smaller rectangles formed.", "hint": "Draw one large rectangle of width $a$ and length $(b+c)$. Draw a vertical line splitting the length into a piece of length $b$ and a piece of length $c$.", "answer": "A single rectangle of width $a$ and total length $b+c$, divided by one vertical line into a left rectangle of dimensions $a$ by $b$ and a right rectangle of dimensions $a$ by $c$. All four of $a$, $b$, $c$ and $b+c$ labelled."}, {"tier": 1, "marks": 5, "prompt": "Using your diagram from the previous question, show that the total area of the large rectangle equals the sum of the areas of the two smaller rectangles, and hence show that $a(b+c) = ab + ac$.", "hint": "Total area = width times total length = $a(b+c)$. Each smaller rectangle has area $a \\times b$ and $a \\times c$ respectively. Total area is also the sum of the two smaller areas because cutting does not lose area.", "answer": "The large rectangle has width $a$ and length $b+c$, so its area is $a(b+c)$. The two smaller rectangles have areas $ab$ and $ac$, so together they have area $ab + ac$. Cutting the rectangle does not change its total area, so the two expressions describe the same area, giving $a(b+c) = ab + ac$."}, {"tier": 1, "marks": 4, "prompt": "Explain why the distributive property $a(b+c) = ab+ac$ also justifies the reverse direction, $ab+ac = a(b+c)$, which is called factoring. Verify this reverse direction numerically using $a = 7$, $b = 3$, $c = 5$.", "answer": "An equation is a statement that two expressions are the same quantity, so it may be read in either direction; proving $a(b+c) = ab+ac$ therefore also establishes $ab+ac = a(b+c)$. Verification: $7(3) + 7(5) = 21 + 35 = 56$ and $7(3+5) = 7(8) = 56$. Both sides equal 56."}, {"tier": 2, "marks": 4, "prompt": "Investigate whether the distributive property extends to three terms inside the bracket: calculate both sides of $a(b+c+d) = ab+ac+ad$ for $a = 2$, $b = 3$, $c = 4$, $d = 5$. State your conjecture.", "answer": "Left side: $2(3+4+5) = 2(12) = 24$. Right side: $2(3) + 2(4) + 2(5) = 6 + 8 + 10 = 24$. Both equal 24. Conjecture: the distributive property extends to any number of terms inside the bracket — the multiplier is applied to each term in turn."}]}, {"heading": "Part 3 — Proving Equivalence Formally", "prerequisiteBox": {"items": ["A.2 checked whether two expressions were equivalent by substituting one number and comparing results — this gives evidence, not proof, because it only tests one value.", "Commutative property: $a + b = b + a$ and $a \\times b = b \\times a$.", "Associative property: $(a + b) + c = a + (b + c)$ and $(a \\times b) \\times c = a \\times (b \\times c)$.", "Distributive property: $a(b+c) = ab+ac$, proved in Part 2 by the area model."]}, "spotlight": {"title": "Verify vs Prove", "body": "'Verify' means to substitute specific numbers and confirm a statement holds for those numbers — this was the method used in A.2. 'Prove' means to show the statement holds for every possible number, using named properties rather than any particular substitution. From this point in the course, when two expressions are claimed to be equivalent, you are expected to prove it, not only verify it."}, "questions": [{"tier": 1, "marks": 2, "prompt": "Determine, using the distributive property, an expanded expression equivalent to $6(2x + 5)$.", "answer": "$6(2x+5) = 6(2x) + 6(5) = 12x + 30$ by the distributive property."}, {"tier": 1, "marks": 2, "prompt": "Consider the two expressions $3(x + 4) + 2x$ and $5x + 12$. Verify they are equivalent by substituting $x = 6$ into both.", "answer": "$3(6+4) + 2(6) = 3(10) + 12 = 30 + 12 = 42$ and $5(6) + 12 = 30 + 12 = 42$. Both give 42, so the expressions agree at $x = 6$."}, {"tier": 1, "marks": 6, "prompt": "Prove that $3(x + 4) + 2x = 5x + 12$ for every value of $x$, using the distributive property and naming each property you use. Explain why this proof is stronger evidence than the single substitution in the previous question.", "hint": "Start by distributing the 3 across $(x+4)$. Then combine like terms, which uses the commutative and associative properties to regroup the $x$-terms together.", "answer": "$3(x+4) + 2x = 3x + 12 + 2x$ (distributive property) $= 3x + 2x + 12$ (commutative property of addition) $= (3x + 2x) + 12$ (associative property of addition) $= 5x + 12$ (distributive property in reverse, since $3x + 2x = (3+2)x$). The proof uses only properties that hold for every number, so it establishes the equality for every value of $x$; the substitution in the previous question tests one value only and could not rule out disagreement elsewhere."}, {"tier": 2, "marks": 6, "prompt": "Prove that $4(2x + 3) - x = 7x + 12$ for every value of $x$, showing every step and naming the property used at each step.", "hint": "Recall from A.2 that subtracting $x$ means adding $(-x)$.", "answer": "$4(2x+3) - x = 8x + 12 - x$ (distributive property) $= 8x + 12 + (-x)$ (definition of subtraction from A.2) $= 8x + (-x) + 12$ (commutative property of addition) $= (8x + (-x)) + 12$ (associative property of addition) $= 7x + 12$ (since $8x - x = (8-1)x = 7x$, the distributive property in reverse)."}, {"tier": 2, "marks": 6, "prompt": "Two expressions are given: $2(3x + 5) + 4$ and $6x + 14$. Determine whether these expressions are equivalent by proving your conclusion using properties, rather than only substituting a number.", "answer": "$2(3x+5) + 4 = 6x + 10 + 4$ (distributive property) $= 6x + (10 + 4)$ (associative property of addition) $= 6x + 14$. The two expressions are therefore equivalent for every value of $x$."}, {"tier": 2, "marks": 5, "prompt": "Deduce, using the distributive property twice, an expression equivalent to $5(x+2) + 3(x+1)$, giving your answer in the form $mx + n$.", "answer": "$5(x+2) + 3(x+1) = 5x + 10 + 3x + 3$ (distributive property, applied to each bracket) $= 5x + 3x + 10 + 3$ (commutative and associative properties of addition) $= 8x + 13$. So $m = 8$ and $n = 13$."}]}, {"heading": "Part 4 — Application: Properties in a Real Context", "prerequisiteBox": {"items": ["A market stall sells items where the total cost can be written as an algebraic expression in the number of items bought.", "Proving two pricing expressions equivalent means a shopper gets the same total cost however the calculation is organised."]}, "spotlight": {"title": "Interpret vs Explain", "body": "'Interpret' asks you to read meaning out of a mathematical result back into the real context it came from. 'Explain' asks for the reasoning behind a mathematical step itself. Question 2 below asks for both, in that order."}, "questions": [{"tier": 1, "marks": 4, "prompt": "A market stall sells notebooks for 3 dollars each and pens for 2 dollars each. A shopper buys $n$ notebooks and $n$ pens (the same number of each). One cashier calculates the total cost as $3n + 2n$. A second cashier calculates it as $n(3 + 2)$. Prove these two totals are equal for every value of $n$, naming the property used.", "answer": "$3n + 2n = n(3) + n(2)$ (commutative property of multiplication) $= n(3 + 2)$ (distributive property, read in reverse) $= 5n$. Since only properties true for every number were used, the two cashiers' totals agree for every value of $n$."}, {"tier": 2, "marks": 5, "prompt": "The stall also charges a fixed 4-dollar bag fee per customer, however many items are bought. A customer buying $n$ notebooks and $n$ pens has total cost $5n + 4$ using the result from the previous question. Interpret what the numbers 5 and 4 each represent in this context, then explain why the fee of 4 dollars cannot be distributed across $n$ the way the 5 dollars was.", "answer": "The 5 is the cost per set of one notebook and one pen (3 + 2 dollars), so it is multiplied by the number of sets $n$. The 4 is the bag fee, charged once per customer, so it does not depend on $n$ at all. The distributive property only applies to a factor multiplying a bracketed sum; the 4 is a separate added term, not a factor of $n$, so there is nothing for it to distribute over. Writing $n(5+4)$ would wrongly charge the bag fee once for every set bought."}, {"tier": 2, "marks": 6, "prompt": "A second stall prices the same combination differently: total cost $= 2(n + 2) + 3n$. Determine whether this second stall's total cost is equivalent to $5n + 4$ from the previous question, proving your answer using properties.", "hint": "Distribute the 2 across $(n+2)$ first.", "answer": "$2(n+2) + 3n = 2n + 4 + 3n$ (distributive property) $= 2n + 3n + 4$ (commutative property of addition) $= (2n + 3n) + 4$ (associative property of addition) $= 5n + 4$ (distributive property in reverse). The two totals are equivalent, so a customer pays the same at either stall for every value of $n$."}]}, {"heading": "Part 5 — Error Analysis: Marcus's Proofs", "prerequisiteBox": {"items": ["A valid use of the distributive property distributes multiplication over addition or subtraction only: $a(b+c) = ab+ac$.", "A valid use of the associative property regroups without swapping order; a valid use of the commutative property swaps order without regrouping — the two are not interchangeable."]}, "spotlight": {"title": "Justify vs Explain", "body": "In error analysis, 'Explain' describes what went wrong in general terms. 'Justify' requires you to give the specific property that was misapplied and state the correct property statement it should have matched, as evidence for your claim."}, "questions": [{"tier": 1, "marks": 5, "prompt": "Marcus is asked to prove $2 \\times (3 \\times 5) = (2 \\times 3) \\times (2 \\times 5)$. He writes: 'This is true by the distributive property, since 2 is being distributed across the multiplication.' Calculate both sides to check whether his equation is even numerically true, then justify why his use of the word 'distributive property' is incorrect, stating what the distributive property actually distributes over.", "hint": "The distributive property is stated as $a(b+c) = ab+ac$ — the bracket must contain a sum or difference, not another product.", "answer": "Left side: $2 \\times (3 \\times 5) = 2 \\times 15 = 30$. Right side: $(2 \\times 3) \\times (2 \\times 5) = 6 \\times 10 = 60$. Since $30 \\neq 60$ the equation is false, so no property could justify it. The distributive property is $a(b+c) = ab+ac$: multiplication distributes over ADDITION (or subtraction), not over multiplication. The correct property for $2 \\times (3 \\times 5)$ is the associative property of multiplication, which gives $(2 \\times 3) \\times 5 = 30$ — the 2 is not repeated."}, {"tier": 1, "marks": 5, "prompt": "Marcus is asked to show that $(5 + 2) + 9 = (5 + 9) + 2$. He writes: 'This is true by the associative property, since I just regrouped the numbers.' Calculate both sides, then justify whether 'associative property' is the correct name for what Marcus actually did, identifying which property was really used.", "hint": "Compare the order the three numbers appear in on each side, not just which brackets are used. Associative keeps the same order and only moves the brackets; commutative changes the order the numbers appear in.", "answer": "Left side: $(5+2)+9 = 7+9 = 16$. Right side: $(5+9)+2 = 14+2 = 16$. The equation is true, but the name is wrong. The numbers appear as $5, 2, 9$ on the left and $5, 9, 2$ on the right, so the ORDER of 2 and 9 has changed — that is the commutative property of addition. The associative property alone would only move brackets, giving $5 + (2+9)$ with the order unchanged. A full justification uses both: $(5+2)+9 = 5+(2+9)$ (associative) $= 5+(9+2)$ (commutative) $= (5+9)+2$ (associative)."}]}, {"heading": "Part 6 — Extension: Squaring a Sum", "prerequisiteBox": {"items": ["The distributive property can be applied more than once inside the same expression.", "$(x + y)$ multiplied by itself can be written as $(x + y)(x + y)$."]}, "spotlight": {"title": "Prove vs Investigate, revisited", "body": "Part 1 asked you to Investigate a pattern from a few numeric cases. This part asks you to Prove the same kind of pattern using properties, so that it holds for every value of the letters, not only the cases you happened to test."}, "geometricReading": {"body": "The four-region square makes the '$2xy$' term visible in a way the symbols alone do not: there are two identical rectangular regions of area $xy$, one above the diagonal split and one below it, and it is exactly this doubling that produces the coefficient 2 in $x^2+2xy+y^2$. A student who only memorises the symbolic identity can easily forget the middle term; a student who has drawn the square rarely does, because the two matching rectangles are impossible to miss."}, "questions": [{"tier": 2, "marks": 3, "prompt": "Investigate the statement $(x + y)^2 = x^2 + y^2$ by calculating both sides for $x = 3$, $y = 4$. State whether the statement appears to be true.", "hint": "Recall $(x+y)^2$ means $(x+y)$ times $(x+y)$, not $x^2$ added to $y^2$ directly.", "answer": "Left side: $(3+4)^2 = 7^2 = 49$. Right side: $3^2 + 4^2 = 9 + 16 = 25$. Since $49 \\neq 25$, the statement is false — squaring a sum is not the same as adding the squares."}, {"tier": 2, "marks": 7, "prompt": "Prove that $(x+y)^2 = x^2+2xy+y^2$ for every value of $x$ and $y$, by writing $(x+y)^2$ as $(x+y)(x+y)$ and applying the distributive property twice. Name each property you use.", "hint": "First distribute the first $(x+y)$ across the second bracket: $(x+y)(x+y) = x(x+y)+y(x+y)$. Then distribute again inside each term, and finally collect the two $xy$-type terms using the commutative property.", "answer": "$(x+y)^2 = (x+y)(x+y)$ (definition of squaring) $= x(x+y) + y(x+y)$ (distributive property, first application) $= x^2 + xy + yx + y^2$ (distributive property, second application, to each term) $= x^2 + xy + xy + y^2$ (commutative property of multiplication, since $yx = xy$) $= x^2 + 2xy + y^2$ (since $xy + xy = (1+1)xy = 2xy$, the distributive property in reverse). Every step names a property true for all numbers, so the identity holds for every value of $x$ and $y$."}, {"tier": 3, "marks": 5, "prompt": "Sketch a square of side length $(x+y)$, divided by one horizontal and one vertical line into four regions of side lengths $x$ and $y$. Interpret each of the four regions' areas, and explain how their total matches the identity $x^2+2xy+y^2$ proved in the previous question.", "answer": "The square has side $x+y$, so its area is $(x+y)^2$. The two cuts produce four regions: one $x$ by $x$ square of area $x^2$, one $y$ by $y$ square of area $y^2$, and two $x$ by $y$ rectangles each of area $xy$. Their total is $x^2 + xy + xy + y^2 = x^2 + 2xy + y^2$. Since cutting the square does not change its area, $(x+y)^2 = x^2+2xy+y^2$; the coefficient 2 is visible as the two identical rectangles."}, {"tier": 2, "marks": 3, "prompt": "Determine an expanded expression equivalent to $(x + 3)^2$, using the identity proved in this part.", "hint": "Match $(x+3)^2$ to the pattern $(x+y)^2$ with $y = 3$.", "answer": "Taking $y = 3$ in $(x+y)^2 = x^2+2xy+y^2$ gives $(x+3)^2 = x^2 + 2(3)x + 3^2 = x^2 + 6x + 9$."}]}, {"heading": "Zone (b) — Pre-Class Prep for B.1: Solving Linear Equations", "prerequisiteBox": {"items": ["An equation such as $3x + 5 = 20$ states that two expressions have the same value.", "In Part 3 of this packet, you proved that performing the same valid operation on an expression keeps it equivalent to what it started as."]}, "spotlight": {"title": "Prep questions are not graded like proofs", "body": "These P-numbered questions build intuition for the next section. You are not expected to solve equations formally yet — only to reason about what keeps a balance fair, using ideas you already have."}, "questions": [{"tier": 1, "marks": 1, "prompt": "A two-pan balance is perfectly level, with unknown weight $x$ grams and a 5-gram weight together on the left pan, and a 20-gram weight on the right pan. Write down the equation that describes this balance.", "answer": "$x + 5 = 20$."}, {"tier": 1, "marks": 1, "prompt": "State what must happen to the right pan of the balance in the previous question if you remove the 5-gram weight from the left pan, in order for the balance to stay level.", "answer": "5 grams must also be removed from the right pan."}, {"tier": 1, "marks": 3, "prompt": "Using your answer to the previous question, determine the value of $x$ for the balance $x + 5 = 20$.", "hint": "If removing 5 grams from the left pan requires removing 5 grams from the right pan too, what number remains on the right?", "answer": "Removing 5 grams from each pan leaves $x$ on the left and $20 - 5 = 15$ on the right, so $x = 15$ grams."}, {"tier": 1, "marks": 3, "prompt": "Consider the balance $3x = 18$, meaning three identical unknown weights together equal 18 grams. Determine the weight of one unknown, explaining your reasoning in terms of splitting the right pan into three equal groups.", "answer": "The three unknowns are identical, so splitting the 18 grams on the right into three equal groups pairs one group with each unknown. Each group is $18 \\div 3 = 6$ grams, so $x = 6$ grams."}]}]$json$::jsonb,
  null,
  null,
  $json${"slug": "key-algebraic-properties-proving-expressions-are-equal", "title": "Key Algebraic Properties: Proving Expressions Are Equal", "section": "A.3", "content_spent": ["Fundraiser ticket ledger: adult 12 dollars, child 6, senior 6 -- revenue 12a+6c+6n, plus a group-discount variant", "Market stall: notebooks 3 dollars, pens 2 dollars, fixed 4-dollar bag fee", "Two-pan balance model (shipped as B.1 prep, so B.1 opened from it)", "(a+b)(a+b) = a^2+2ab+b^2 proved by double distribution -- spent as a RESULT, though not yet as a factoring tool"], "where_it_left_off": "Ends having replaced A.1/A.2's numeric checking with property-based proof. Students conjectured a+b=b+a and a*b=b*a from numeric evidence, found subtraction and division fail both commutativity and associativity, stated the three properties symbolically, then proved equivalences step by step NAMING the property at each step (3(x+4)+2(x+4)=5(x+4) treating (x+4) as a single quantity; 4(2x+3y)+5(2x+3y)=18x+27y). CRUCIALLY FOR WHAT FOLLOWS: proved (a+b)(a+b) = a^2 + 2ab + b^2 by applying the distributive property TWICE -- the double-distribution machine is already built and already justified. Applied to a fundraiser revenue ledger, rewriting 12a+6c+6n as 12a+6(c+n). Did NOT solve a single equation (reserved for B.1; only the B.1 pre-class prep, a two-pan balance with x+5=12 and 3x=18, points at it). Did NOT run double distribution BACKWARDS: every expansion in this packet goes product -> sum. No expression was ever turned from a sum back into a product except A.1's single common-factor case 30(2a+c). Factoring as a named idea has not happened yet.", "notation_conventions": ["A proof step must NAME the property that licenses it -- justification is written, not implied", "New command terms: Prove, Investigate, Verify, Distinguish, Deduce", "Prove vs Verify made explicit: Verify = check given values, Prove = establish for every value", "A bracketed expression may be treated as a single quantity, e.g. (x+4) collected like a term", "Continues Clev's Marks, tier stars, command-term strip from A.1/A.2", "CCSS mapping: HSA.SSE.A.2 (use the structure of an expression to identify ways to rewrite it) -- PRIMARY; HSA.APR.A.1 (polynomials are closed under addition, subtraction and multiplication); HSA.APR.C.4 (prove polynomial identities), evidenced by the proof of (a+b)(a+b) = a^2+2ab+b^2; 7.EE.A.1; MP.3 (construct viable arguments) and MP.7."], "tok_provocations_used": ["Can a finite number of numeric checks ever justify a claim about every possible value, or does that always need a different kind of argument?", "Is the commutative property a fact about numbers that was always waiting to be noticed, or a rule mathematicians agreed to build number systems around?"], "vocabulary_introduced": ["commutative property", "associative property", "distributive property (named formally; used informally since A.1)", "counterexample", "proof (as distinct from verification)", "identity"], "misconceptions_planted": ["Distributing to only the first term inside a bracket: 5(x+2) = 5x + 2", "Assuming multiplication distributes over multiplication: 2*(3*5) = (2*3)*(2*5)"], "international_mindedness_used": ["Liu Hui (3rd century CE, China) -- dissection proof, cutting and rearranging a rectangle", "al-Karaji (10th-11th century, Baghdad) -- algebra as operations on symbols independent of the numbers they stand for"]}$json$::jsonb,
